mapper.select:
SELECT t.task_no, t.project_no, p.project_name AS projectName, t.task_title, t.task_content, t.assigned_member_no, t.task_status, t.task_order, t.task_start, t.task_end, t.task_category, t.task_priority, t.task_writer_no, t.task_ctime, t.task_utime FROM task t INNER JOIN project p ON t.project_no = p.project_no WHERE /* 종료된 프로젝트 제외 */ p.project_status = 'active'
/* private 프로젝트 제외 */ AND p.project_visibility != 'private'
/* 현재 로그인 사용자가 프로젝트의 active 회원인지 확인 */ AND EXISTS ( SELECT 1 FROM project_member pm WHERE pm.project_no = p.project_no AND pm.emp_no = #{empNo} AND pm.project_member_status = 'active' )
/* Soft Delete된 업무 제외 */ AND t.task_deleted = 'N'
AND ( REPLACE( LOWER(t.task_title), ' ', '' ) LIKE '%' || REPLACE( LOWER(#{keyword}), ' ', '' ) || '%'
OR
REPLACE( LOWER(t.task_content), ' ', '' ) LIKE '%' || REPLACE( LOWER(#{keyword}), ' ', '' ) || '%' )
ORDER BY t.task_ctime DESC

SELECT r.project_record_no AS projectRecordNo, r.project_no AS projectNo, p.project_name AS projectName,
/* 기록 작성자 */ r.project_record_writer_no AS projectRecordWriterNo,
writer_pm.emp_no AS writerEmpNo,
writer_emp.emp_name AS writerName,
/* 기록 수정자 */ r.project_record_modifier_no AS projectRecordModifierNo,
/* 기록 타입 */ r.project_record_type AS projectRecordType,
/* 제목 */ r.project_record_title AS projectRecordTitle,
/* 내용 */ r.project_record_content AS projectRecordContent,
/* 날짜 */ r.project_record_ctime AS projectRecordCtime,
r.project_record_utime AS projectRecordUtime,
/* ISSUE 정보 */ i.issue_status AS issueStatus,
i.issue_resolution AS issueResolution,
i.issue_resolved_at AS issueResolvedAt
FROM project_record r
/* 프로젝트 */ INNER JOIN project p ON r.project_no = p.project_no
/* 기록 작성자 project_member */ LEFT JOIN project_member writer_pm ON r.project_record_writer_no = writer_pm.project_member_no
/* 기록 작성자 emp */ LEFT JOIN emp writer_emp ON writer_pm.emp_no = writer_emp.emp_no
/* ISSUE 기록 */ LEFT JOIN project_record_issue i ON r.project_record_no = i.project_record_no
WHERE /* 종료된 프로젝트 제외 */ p.project_status = 'active'
/* private 프로젝트 제외 */ AND p.project_visibility != 'private'
/* 현재 로그인 사용자가 프로젝트의 active 회원인지 확인 */ AND EXISTS ( SELECT 1 FROM project_member pm WHERE pm.project_no = p.project_no AND pm.emp_no = #{empNo} AND pm.project_member_status = 'active' )
AND ( /* 기록 제목 */ REPLACE( LOWER(r.project_record_title), ' ', '' ) LIKE '%' || REPLACE( LOWER(#{keyword}), ' ', '' ) || '%'
OR
/* 기록 내용 - CLOB */ DBMS_LOB.INSTR( REGEXP_REPLACE( LOWER(r.project_record_content), '[[:space:]]', '' ), REGEXP_REPLACE( LOWER(#{keyword}), '[[:space:]]', '' ) ) > 0 )
ORDER BY r.project_record_ctime DESC

SELECT e.emp_no AS empNo, e.emp_name AS empName, e.emp_email AS empEmail,
d.dept_name AS deptName,
p.position_name AS positionName,
e.emp_contact AS empContact,
/* 사용자 프로필 이미지 */ ep.attach_no AS attachNo
FROM emp e
INNER JOIN dept d ON e.emp_dept_no = d.dept_no
INNER JOIN position p ON e.emp_position_no = p.position_no
/* emp → emp_profile → attach */ LEFT JOIN emp_profile ep ON e.emp_no = ep.emp_no
WHERE e.emp_no = #{_parameter}
